var av=15.75, as_=17.8, ac=0.711, asym=23.7;
function pair(A,Z){ var N=A-Z; if(Z%2===0&&N%2===0) return 12/Math.sqrt(A); if(Z%2===1&&N%2===1) return -12/Math.sqrt(A); return 0; }
function Bof(A,Z){ return av*A - as_*Math.pow(A,2/3) - ac*Z*(Z-1)/Math.pow(A,1/3) - asym*(A-2*Z)*(A-2*Z)/A + pair(A,Z); }
function Zbest(A){ return Math.max(1, Math.round(A/(2+0.015*Math.pow(A,2/3)))); }

var padL=44, padR=14, padT=16, padB=30;
var Amax=250, Bmax=10;
function X(a){ return padL + (a/Amax)*(W-padL-padR); }
function Y(b){ return H-padB - (b/Bmax)*(H-padT-padB); }

ctx.lineWidth=1;
ctx.strokeStyle=C.faint;
ctx.font="12px ui-sans-serif, system-ui, sans-serif";
ctx.fillStyle=C.figure;
for(var b=2;b<=8;b+=2){
  ctx.beginPath(); ctx.moveTo(padL,Y(b)); ctx.lineTo(W-padR,Y(b)); ctx.stroke();
  ctx.textAlign="right"; ctx.fillText(b.toFixed(0), padL-6, Y(b)+4);
}
ctx.strokeStyle=C.rule;
ctx.beginPath(); ctx.moveTo(padL,Y(0)); ctx.lineTo(W-padR,Y(0)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(padL,Y(0)); ctx.lineTo(padL,padT); ctx.stroke();
ctx.textAlign="center";
for(var a=50;a<=250;a+=50){ ctx.fillText(String(a), X(a), H-padB+15); }
ctx.fillText("mass number A", (padL+W-padR)/2, H-4);
ctx.save(); ctx.translate(11,(padT+H-padB)/2); ctx.rotate(-Math.PI/2);
ctx.fillText("B/A  (MeV per nucleon)",0,0); ctx.restore();

ctx.strokeStyle=C.accent; ctx.lineWidth=2; ctx.beginPath();
for(var A=4;A<=Amax;A+=1){
  var z=Zbest(A); var ba=Bof(A,z)/A;
  if(A===4) ctx.moveTo(X(A),Y(ba)); else ctx.lineTo(X(A),Y(ba));
}
ctx.stroke();

var Ap=56, zp=Zbest(56), bp=Bof(56,zp)/56;
ctx.strokeStyle=C.rule; ctx.lineWidth=1; ctx.setLineDash([3,4]);
ctx.beginPath(); ctx.moveTo(X(Ap),Y(0)); ctx.lineTo(X(Ap),Y(bp)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle=C.figure; ctx.textAlign="left";
ctx.fillText("iron-56, the peak", X(Ap)+6, Y(bp)-8);

var As=Math.round(p.A); var Zs=Zbest(As); var Bs=Bof(As,Zs); var bas=Bs/As;
ctx.fillStyle=C.ink;
ctx.beginPath(); ctx.arc(X(As),Y(bas),5,0,Math.PI*2); ctx.fill();
ctx.textAlign = As>170 ? "right" : "left";
ctx.fillText("A="+As, X(As)+(As>170?-8:8), Y(bas)+16);

ctx.fillStyle=C.figure; ctx.textAlign="center";
ctx.fillText("fusion runs this way →", X(28), Y(2.0));
ctx.fillText("← fission runs this way", X(190), Y(2.0));

out.note = "A = "+As+", most stable Z ≈ "+Zs+"   B/A = "+bas.toFixed(2)+" MeV   total B = "+Bs.toFixed(0)+" MeV";

var av=15.75, as_=17.8, ac=0.711, asym=23.7;
function pair(A,Z){ var N=A-Z; if(Z%2===0&&N%2===0) return 12/Math.sqrt(A); if(Z%2===1&&N%2===1) return -12/Math.sqrt(A); return 0; }
var Z=Math.round(p.Z), N=Math.round(p.N), A=Z+N;
var B = av*A - as_*Math.pow(A,2/3) - ac*Z*(Z-1)/Math.pow(A,1/3) - asym*(A-2*Z)*(A-2*Z)/A + pair(A,Z);
if(B<0) B=0;
var mH=1.007825, mn=1.008665;
var parts = Z*mH + N*mn;
var mass = parts - B/931.5;

ctx.font="12px ui-sans-serif, system-ui, sans-serif";
var padT=26, padB=42;
var base=H-padB;
var top=padT;
var scale=(base-top)/parts;
var wBar=Math.min(90,(W-140)/2);
var x1=W*0.24-wBar/2, x2=W*0.68-wBar/2;

ctx.fillStyle=C.faint;
ctx.fillRect(x1, base-parts*scale, wBar, parts*scale);
ctx.strokeStyle=C.rule; ctx.lineWidth=1;
ctx.strokeRect(x1, base-parts*scale, wBar, parts*scale);

ctx.fillStyle=C.accent;
ctx.fillRect(x2, base-mass*scale, wBar, mass*scale);
ctx.strokeRect(x2, base-mass*scale, wBar, mass*scale);

ctx.strokeStyle=C.ink; ctx.setLineDash([3,4]);
ctx.beginPath(); ctx.moveTo(x1, base-parts*scale); ctx.lineTo(x2+wBar+22, base-parts*scale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x2, base-mass*scale); ctx.lineTo(x2+wBar+22, base-mass*scale); ctx.stroke();
ctx.setLineDash([]);

var ax=x2+wBar+14;
ctx.strokeStyle=C.ink; ctx.lineWidth=1.5;
ctx.beginPath(); ctx.moveTo(ax, base-parts*scale); ctx.lineTo(ax, base-mass*scale); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax-4, base-parts*scale+6); ctx.lineTo(ax, base-parts*scale); ctx.lineTo(ax+4, base-parts*scale+6); ctx.stroke();
ctx.beginPath(); ctx.moveTo(ax-4, base-mass*scale-6); ctx.lineTo(ax, base-mass*scale); ctx.lineTo(ax+4, base-mass*scale-6); ctx.stroke();

ctx.fillStyle=C.ink; ctx.textAlign="center";
ctx.fillText("mass defect", (ax+W)/2 - 6, base-(parts+mass)*scale/2 - 2);
ctx.fillStyle=C.figure;
ctx.fillText("= B / 931.5", (ax+W)/2 - 6, base-(parts+mass)*scale/2 + 13);

ctx.fillStyle=C.figure; ctx.textAlign="center";
ctx.fillText(Z+" free protons +", x1+wBar/2, base+16);
ctx.fillText(N+" free neutrons", x1+wBar/2, base+30);
ctx.fillText("the bound nucleus", x2+wBar/2, base+16);
ctx.fillText("A = "+A, x2+wBar/2, base+30);
ctx.fillStyle=C.ink;
ctx.fillText(parts.toFixed(4)+" u", x1+wBar/2, base-parts*scale-8);
ctx.fillText(mass.toFixed(4)+" u", x2+wBar/2, base-mass*scale-8);

out.note = "defect "+(parts-mass).toFixed(4)+" u × 931.5 = B "+B.toFixed(1)+" MeV, so B/A = "+(B/A).toFixed(2)+" MeV per nucleon";

var av=15.75, as_=17.8, ac=0.711, asym=23.7;
function pair(A,Z){ var N=A-Z; if(Z%2===0&&N%2===0) return 12/Math.sqrt(A); if(Z%2===1&&N%2===1) return -12/Math.sqrt(A); return 0; }
function Zbest(A){ return Math.max(1, Math.round(A/(2+0.015*Math.pow(A,2/3)))); }
function Bof(A){ var z=Zbest(A); return av*A - as_*Math.pow(A,2/3) - ac*z*(z-1)/Math.pow(A,1/3) - asym*(A-2*z)*(A-2*z)/A + pair(A,z); }

var A=Math.round(p.A);
var f=p.split;
var A1=Math.round(A*f), A2=A-A1;
if(A1<1){A1=1;A2=A-1;}
var Q = Bof(A1)+Bof(A2)-Bof(A);

var cyc=3.2; var ph=(t%cyc)/cyc;
var grow = ph<0.45 ? 0 : (ph-0.45)/0.55;
var R=function(n){ return 1.9*Math.pow(n,1/3)*(Math.min(W,H)/70); };

ctx.font="12px ui-sans-serif, system-ui, sans-serif";
var cy=H*0.46, cx=W*0.5;
var sep=grow*Math.min(W*0.30, 150);

if(ph<0.45){
  var wob=1+0.10*Math.sin(ph*14);
  ctx.fillStyle=C.accent;
  ctx.beginPath(); ctx.ellipse(cx, cy, R(A)*wob, R(A)/wob, 0, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle=C.paper; ctx.textAlign="center";
  ctx.fillText("A="+A, cx, cy+4);
} else {
  ctx.fillStyle=C.accent;
  ctx.beginPath(); ctx.arc(cx-sep, cy, R(A1),0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(cx+sep, cy, R(A2),0,Math.PI*2); ctx.fill();
  ctx.fillStyle=C.paper; ctx.textAlign="center";
  ctx.fillText("A="+A1, cx-sep, cy+4);
  ctx.fillText("A="+A2, cx+sep, cy+4);
  ctx.strokeStyle=C.ink; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(cx-sep-R(A1)-6, cy); ctx.lineTo(cx-sep-R(A1)-6-18*grow, cy); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(cx+sep+R(A2)+6, cy); ctx.lineTo(cx+sep+R(A2)+6+18*grow, cy); ctx.stroke();
}

ctx.fillStyle=C.figure; ctx.textAlign="center";
ctx.fillText(Q>0 ? "energy comes out: the fragments fly apart" : "energy must be put in: this will not happen on its own", W/2, H-26);
ctx.fillStyle=C.ink;
ctx.fillText("Q = B(A1) + B(A2) − B(A) = "+Q.toFixed(0)+" MeV", W/2, H-8);

ctx.textAlign="left"; ctx.fillStyle=C.figure;
ctx.fillText("B/A parent "+(Bof(A)/A).toFixed(2)+" MeV", 10, 16);
ctx.fillText("B/A fragments "+((Bof(A1)+Bof(A2))/A).toFixed(2)+" MeV", 10, 32);

out.note = "A "+A+" → "+A1+" + "+A2+"   Q = "+Q.toFixed(1)+" MeV  ("+(Q/A).toFixed(2)+" MeV per nucleon)";
